1	package net.officefloor.hq.app.sheet;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.time.Instant;
6	import net.officefloor.hq.app.Audit;
7	import java.time.LocalDate;
8	import net.officefloor.hq.app.rollup.Rollups;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Transactional;
11	
12	/** Loads sheets by id; an id never loaded before starts a new, empty sheet. */
13	@Service
14	public class SheetService {
15	
16	    private final SheetRepository sheets;
17	    private final Rollups rollups;
18	    private final Audit audit;
19	
20	    public SheetService(SheetRepository sheets, Rollups rollups, Audit audit) {
21	        this.sheets = sheets;
22	        this.rollups = rollups;
23	        this.audit = audit;
24	    }
25	
26	    /** Load a sheet; a new sheet's today starts as the real date. */
27	    @Transactional
28	    public synchronized Sheet load(String id) {
29	        return sheets.findById(id).orElseGet(() -> sheets.save(new Sheet(id, Instant.now(), LocalDate.now())));
30	    }
31	
32	    /**
33	     * The sheet's today. Every date-dependent decision and every default date on a sheet uses
34	     * this, never the real clock.
35	     */
36	    @Transactional(readOnly = true)
37	    public LocalDate today(String id) {
38	        return load(id).getToday();
39	    }
40	
41	    /**
42	     * Take the sheet's lock, holding it until the caller's transaction ends, so changes that check
43	     * the sheet's other rows before writing are made one at a time.
44	     */
45	    @Transactional
46	    public Sheet lock(String id) {
47	        load(id);
48	        return sheets.findLockedById(id).orElseThrow();
49	    }
50	
51	    /** Change the sheet's today, auditing the figures that moves. */
52	    @Transactional
53	    public synchronized Sheet setToday(String id, String user, LocalDate today) {
54	        Sheet sheet = load(id);
55	        Rollups.Rollup before = rollups.take(id);
56	        sheet.setToday(today);
57	        Sheet saved = sheets.saveAndFlush(sheet);
58	        rollups.audit(id, user, before);
59	        return saved;
60	    }
61	
62	    /** The sheet's clerk limit; null when there is none. */
63	    @Transactional(readOnly = true)
64	    public BigDecimal clerkLimit(String id) {
65	        return load(id).getClerkLimit();
66	    }
67	
68	    /** Record the sheet's clerk limit (null: no limit) from a date (null: the sheet's today), auditing the change. */
69	    @Transactional
70	    public Sheet setClerkLimit(String id, String user, BigDecimal limit, LocalDate from) {
71	        return setDated(id, user, Sheet.CLERK_LIMIT, money(limit), from, false);
72	    }
73	
74	    /** Record the sheet's cap (null: no cap) from a date, auditing the change and the figures it moves. */
75	    @Transactional
76	    public Sheet setCap(String id, String user, BigDecimal cap, LocalDate from) {
77	        return setDated(id, user, Sheet.CAP, money(cap), from, true);
78	    }
79	
80	    /** Record the sheet's proof threshold (null: none) from a date, auditing the change. */
81	    @Transactional
82	    public Sheet setProofThreshold(String id, String user, BigDecimal threshold, LocalDate from) {
83	        return setDated(id, user, Sheet.PROOF_THRESHOLD, money(threshold), from, false);
84	    }
85	
